using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text;

namespace PaymentProcessor
{
    public sealed class TransactionBatch
    {
        public string MerchantId { get; set; }
        public List<LineItem> Items { get; set; } = new List<LineItem>();
        public DateTime SubmittedAt { get; set; }
    }

    public sealed class LineItem
    {
        public string ProductCode { get; set; }
        public int Quantity { get; set; }
        public int UnitPriceCents { get; set; }
        public int DiscountBasisPoints { get; set; }
    }

    public sealed class BatchValidator
    {
        private const int MaxBatchTotalCents = 10_000_000; // $100,000 limit
        private const int MaxSingleItemCents = 1_000_000;  // $10,000 per line

        public bool ValidateLineItem(LineItem item)
        {
            if (item.Quantity <= 0 || item.Quantity > 9999)
                return false;
            if (item.UnitPriceCents <= 0 || item.UnitPriceCents > MaxSingleItemCents)
                return false;
            if (item.DiscountBasisPoints < 0 || item.DiscountBasisPoints > 5000)
                return false;
            return true;
        }

        public bool ValidateBatchTotal(TransactionBatch batch)
        {
            long runningTotal = 0;
            foreach (var item in batch.Items)
            {
                long lineTotal = ComputeLineTotal(item);
                runningTotal += lineTotal;
            }
            return runningTotal <= MaxBatchTotalCents;
        }

        private long ComputeLineTotal(LineItem item)
        {
            long gross = (long)item.Quantity * item.UnitPriceCents;
            long discount = gross * item.DiscountBasisPoints / 10000;
            return gross - discount;
        }
    }

    public sealed class SettlementEngine
    {
        private readonly BatchValidator _validator = new BatchValidator();

        public SettlementResult ProcessBatch(TransactionBatch batch)
        {
            foreach (var item in batch.Items)
            {
                if (!_validator.ValidateLineItem(item))
                    return SettlementResult.Rejected("Invalid line item");
            }

            if (!_validator.ValidateBatchTotal(batch))
                return SettlementResult.Rejected("Batch exceeds maximum");

            long settlementAmountCents = ComputeSettlement(batch);
            return SettlementResult.Approved(settlementAmountCents);
        }

        private long ComputeSettlement(TransactionBatch batch)
        {
            long total = 0;
            foreach (var item in batch.Items)
            {
                long lineGross = (long)item.Quantity * item.UnitPriceCents;
                long discountAmount = lineGross * item.DiscountBasisPoints / 10000;
                long lineNet = lineGross - discountAmount;
                total += lineNet;
            }
            return total;
        }
    }

    public sealed class SettlementResult
    {
        public bool IsApproved { get; private set; }
        public long AmountCents { get; private set; }
        public string Reason { get; private set; }

        public static SettlementResult Approved(long amount) =>
            new SettlementResult { IsApproved = true, AmountCents = amount };
        public static SettlementResult Rejected(string reason) =>
            new SettlementResult { IsApproved = false, Reason = reason };
    }

    public sealed class BatchFileParser
    {
        public TransactionBatch Parse(Stream input)
        {
            using var reader = new StreamReader(input, Encoding.UTF8);
            var batch = new TransactionBatch();

            string header = reader.ReadLine();
            if (header == null) throw new FormatException("Empty file");
            batch.MerchantId = header.Trim();
            batch.SubmittedAt = DateTime.UtcNow;

            string line;
            while ((line = reader.ReadLine()) != null)
            {
                var parts = line.Split(',');
                if (parts.Length != 4)
                    throw new FormatException($"Invalid line format: {line}");

                batch.Items.Add(new LineItem
                {
                    ProductCode = parts[0].Trim(),
                    Quantity = int.Parse(parts[1].Trim()),
                    UnitPriceCents = int.Parse(parts[2].Trim()),
                    DiscountBasisPoints = int.Parse(parts[3].Trim())
                });
            }
            return batch;
        }
    }

    public class Program
    {
        public static void Main(string[] args)
        {
            var parser = new BatchFileParser();
            var engine = new SettlementEngine();

            using var fs = File.OpenRead(args[0]);
            var batch = parser.Parse(fs);
            var result = engine.ProcessBatch(batch);

            if (result.IsApproved)
                Console.WriteLine($"Settlement approved: ${result.AmountCents / 100.0:F2}");
            else
                Console.WriteLine($"Rejected: {result.Reason}");
        }
    }
}
